// document NIE JEST czescia samego jezyka JavaScript - jest to interfejs
// (API) dostarczany przez PRZEGLADARKE, ktora reprezentuje zaladowana
// strone HTML jako drzewo obiektow. Node.js uruchamia JavaScript POZA
// przegladarka (np. na serwerze), wiec nie ma 'strony' do reprezentowania -
// obiekt document po prostu nie istnieje w tym srodowisku, chyba ze
// zainstaluje sie dodatkowa biblioteke symulujaca DOM.

// HTML to KOD ZRODLOWY strony - tekstowy plik z znacznikami, ktory
// przegladarka odczytuje raz, przy ladowaniu strony.
//
// DOM to 'ZYWA', drzewiasta STRUKTURA OBIEKTOW JavaScript, ktora
// przegladarka TWORZY na podstawie HTML - kazdy znacznik staje sie
// osobnym 'wezlem' tego drzewa. W przeciwienstwie do 'plaskiego' HTML,
// DOM MOZE byc modyfikowany 'na zywo' przez JavaScript (dodawanie,
// usuwanie, zmiana elementow) - kazda taka zmiana natychmiast
// aktualizuje to, co widac na ekranie, bez potrzeby ponownego
// wczytywania calej strony.

function opisDokumentu() {
  return { title: document.title, url: document.URL };
}

console.log(opisDokumentu());

// "Wezel" (node) to OGOLNA kategoria obejmujaca kazdy obiekt drzewa DOM -
// nie tylko znaczniki HTML, ale rowniez tekst wewnatrz nich czy komentarze.
// "Element" to WEZSZE pojecie - wezel reprezentujacy KONKRETNIE znacznik
// HTML (np. <div>, <p>). Kazdy element JEST wezlem, ale nie kazdy wezel
// jest elementem (np. sam tekst wewnatrz <p>Czesc</p> to wezel tekstowy,
// a nie element).

// Trzy glowne, zawsze dostepne "galezie" drzewa DOM:
// 1. document.documentElement - znacznik <html>, korzen calego drzewa
// 2. document.head - znacznik <head>
// 3. document.body - znacznik <body>, widoczna trescs strony

// HTML jest "plaskim", statycznym tekstem zrodlowym - przegladarka
// odczytuje go raz, przy ladowaniu strony, i na jego podstawie buduje DOM.
// DOM nazywany jest "zywa" struktura, poniewaz JavaScript moze go
// modyfikowac W DOWOLNYM MOMENCIE dzialania strony (dodawac, usuwac,
// zmieniac elementy) - kazda taka zmiana natychmiast aktualizuje to,
// co widac na ekranie, bez ponownego wczytywania calej strony z serwera.

try {
  console.log(document.title);
} catch (e) {
  console.log(e.name); // "ReferenceError"
}

if (typeof document !== "undefined") {
  console.log("Dostepna przegladarka");
} else {
  console.log("Brak przegladarki");
}

// 1. Przegladarka pobiera plik HTML i zaczyna go czytac od gory do dolu.
// 2. Dla kazdego napotkanego znacznika tworzy odpowiadajacy mu wezel
//    (obiekt) w pamieci.
// 3. Zagniezdzenie i kolejnosc znacznikow w HTML sa odwzorowywane jako
//    relacje rodzic-dziecko i rodzenstwo w drzewie DOM.
// 4. Gdy drzewo jest gotowe, przegladarka renderuje strone na jego
//    podstawie, polaczonego z regulami CSS.
// 5. JavaScript moze pozniej odczytac lub zmodyfikowac to drzewo -
//    kazda zmiana automatycznie przebudowuje widok na ekranie.

// HTML jest jak rysunek architektoniczny budynku - plaski, statyczny
// opis tego, jak budynek MA wygladac, przygotowany raz przez architekta.
// DOM jest jak faktyczny, "zywy" budynek zbudowany na podstawie tego
// rysunku - kazdy pokoj (element) jest polaczony z sasiednimi pokojami
// (rodzic/dziecko/rodzenstwo), a w przeciwienstwie do samego rysunku,
// budynek MOZNA przebudowac w trakcie uzytkowania (przez JavaScript).

// Wirtualny DOM Reacta to jedynie WEWNETRZNA reprezentacja w pamieci,
// uzywana do wydajnego obliczania, CO dokladnie sie zmienilo miedzy
// kolejnymi stanami aplikacji. Ale to, co faktycznie widac na ekranie,
// zawsze pochodzi z PRAWDZIWEGO drzewa DOM przegladarki - React na
// koncu i tak wywoluje te same, rzeczywiste operacje DOM (np.
// tworzenie/usuwanie elementow), tylko robi to za programiste,
// w sposob zoptymalizowany.

const liczbaBody = document.body.childElementCount;
const liczbaHead = document.head.childElementCount;
console.log(liczbaBody, liczbaHead, liczbaBody + liczbaHead);

// DOM NIE jest czescia samego jezyka JavaScript (tak jak Array czy Map,
// ktore sa zdefiniowane w specyfikacji jezyka i dzialaja WSZEDZIE, takze
// w Node.js) - DOM to interfejs (API) DOSTARCZANY PRZEZ PRZEGLADARKE,
// ktora reprezentuje zaladowana strone jako drzewo obiektow. Dlatego
// document istnieje tylko tam, gdzie jest przegladarka - w Node.js
// (bez dodatkowych bibliotek) go nie ma, w przeciwienstwie np. do
// new Map(), ktore dziala identycznie w obu srodowiskach.

console.log(document.documentElement?.lang);
// Optional chaining (?.) przydalby sie, gdyby document.documentElement
// moglo czasem byc null lub undefined - wtedy zapis bez "?." rzucilby
// TypeError przy probie odczytu .lang. W praktyce documentElement
// zawsze istnieje po zaladowaniu strony, ale to bezpieczny, defensywny
// nawyk przy nawigacji po drzewie DOM (przyda sie bardziej w lekcji 2).

function czyMaTresc() {
  return document.head.childElementCount > 0;
}

console.log(czyMaTresc());

console.log(document.body === document.body);
// Zawsze true - document.body kazdorazowo zwraca REFERENCJE do TEGO
// SAMEGO obiektu w pamieci (znacznika <body>), a nie nowa kopie.
// Porownanie === dwoch referencji do tego samego obiektu zawsze daje true.

// DOM to drzewiasta reprezentacja strony HTML w postaci obiektow
// JavaScript, tworzona automatycznie przez przegladarke po zaladowaniu
// strony. Obiekt document jest globalnym korzeniem tego drzewa, z trzema
// zawsze dostepnymi "galeziami": documentElement, head i body. DOM jest
// interfejsem dostarczanym wylacznie przez przegladarke, wiec nie jest
// dostepny w "golym" srodowisku Node.js.

quiz.question:
Co wypisze poniższy kod?
if (typeof window === "undefined") {
  console.log("Node");
} else {
  console.log("Przegladarka");
}

Co wypisze poniższy kod?
try {
  document.body.childElementCount;
  console.log("OK");
} catch (e) {
  console.log(e.name);
}

Co wypisze poniższy kod?
try {
  const el = document.documentElement;
  console.log(el.lang);
} catch (e) {
  console.log(e.message.includes("document"));
}

Co wypisze poniższy kod?
const env = typeof document === "undefined" ? "serwer" : "przegladarka";
console.log(env);

Co wypisze poniższy kod?
try {
  console.log(document);
} catch (e) {
  console.log(e instanceof ReferenceError);
}

Co wypisze poniższy kod?
function pobierzTytul() {
  return document.title;
}
try {
  pobierzTytul();
} catch (e) {
  console.log("Blad: " + e.name);
}
